package com.yeyamo_mobile.api.auth_service.event;
import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.auth_service.enums.*;import com.yeyamo_mobile.api.auth_service.models.*;import com.yeyamo_mobile.api.auth_service.repository.*;
class PartnerApprovedConsumerTests{@Test void grantsPartnerRoleOnce()throws Exception{UserRepository users=mock(UserRepository.class);RoleRepository roles=mock(RoleRepository.class);AuthProcessedEventRepository processed=mock(AuthProcessedEventRepository.class);AuthEventOutbox outbox=mock(AuthEventOutbox.class);User user=new User();user.setId(42L);user.setRoles(new HashSet<>());Role role=new Role(2L,Roles.PARTNER,LabelRole.PARTENAIRE);when(processed.existsById(any())).thenReturn(false);when(users.findById(42L)).thenReturn(Optional.of(user));when(roles.findByCode(Roles.PARTNER)).thenReturn(Optional.of(role));String event="{\"eventId\":\"11111111-1111-1111-1111-111111111111\",\"eventType\":\"partner.approved\",\"correlationId\":\"req-1\",\"payload\":{\"ownerUserId\":\"42\"}}";new PartnerApprovedConsumer(new ObjectMapper(),users,roles,processed,outbox).consume(event);verify(users).save(user);verify(outbox).roleAdded(user,"PARTNER","req-1");verify(processed).save(any(AuthProcessedEvent.class));}}
